#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

public sealed class CheeseAppearanceIntegrationTests
{
    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Sports(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static object Get(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static void Set(object owner,string name,object value){if(owner.GetType().GetField(name,Any) is FieldInfo field)field.SetValue(owner,value);else owner.GetType().GetProperty(name,Any).SetValue(owner,value);}
    static object Call(object owner,string name,params object[] args)=>owner.GetType().GetMethods(Any).Single(method=>method.Name==name&&method.GetParameters().Length==args.Length).Invoke(owner,args);
    static object Registry(string name,params object[] args)=>Sports("SportsParticipantRegistry").GetMethod(name).Invoke(null,args);
    Component match;IDisposable lease;GameObject isolation;Component[] trucks;object[] hosts;string[] ids;
    [TearDown]public void Cleanup(){Time.timeScale=1;if(match!=null)Call(match,"ChangeSetup");if(isolation!=null)UnityEngine.Object.DestroyImmediate(isolation);Registry("ForgetCache");lease?.Dispose();lease=null;}
    static void Save(string id,string body){var draft=Registry("GetAppearance",id);Set(draft,"bodyId",body);((IList)Get(draft,"selections")).Clear();Registry("TrySetAppearance",id,draft);Registry("ForgetCache");Assert.That(Get(Registry("GetAppearance",id),"bodyId"),Is.EqualTo(body));}
    IEnumerator Load()
    {
        lease=(IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"CheeseAppearance"+Guid.NewGuid().ToString("N")});Registry("ForgetCache");isolation=new GameObject("Actual Cheese four-owner appearance fixture");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Sports("SportsProbeInputIsolation"));EditorSceneManager.LoadSceneInPlayMode("Assets/TruckCheeseRolling/Scenes/TruckCheeseRolling.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=(Component)UnityEngine.Object.FindAnyObjectByType(Type.GetType("LWS.TruckCheeseRolling.CheeseMatch, Assembly-CSharp",true));Assert.That(match,Is.Not.Null);Set(Get(match,"setup"),"count",4);Call(match,"AllAI");trucks=((Array)Get(match,"trucks")).Cast<Component>().ToArray();Assert.That(trucks.Length,Is.EqualTo(16));hosts=((Array)Get(match,"appearanceHosts")).Cast<object>().ToArray();Assert.That(hosts.Length,Is.EqualTo(4),"Run BindMissingCheeseParticipantHosts first.");ids=new string[4];for(int i=0;i<4;i++){ids[i]=(string)Get(Registry("Create","Same Cheese Racer"),"id");Registry("UseInSeat",i,ids[i]);Save(ids[i],i%2==0?"truck.fire":"novelty.icecream");Assert.That(((Component)hosts[i]).transform,Is.SameAs(trucks[i].transform));Assert.That(Get(hosts[i],"participantSlot"),Is.EqualTo(i));}Call(match,"RefreshParticipants",false);foreach(var background in trucks.Skip(4))Assert.That(background.GetComponent(Sports("SportsTruckAppearanceHost")),Is.Null);
    }
    IEnumerable<Component> Physical()=>trucks.SelectMany(t=>t.GetComponentsInChildren<Component>(true)).Where(c=>c is Rigidbody||c is Collider).Distinct();
    static string Config(Component c){if(c is Rigidbody b)return b.mass+"/"+b.centerOfMass.ToString("R")+"/"+b.inertiaTensor.ToString("R")+"/"+b.linearDamping+"/"+b.angularDamping+"/"+b.constraints;var shape=(Collider)c;string s=shape.isTrigger+"/"+shape.contactOffset+"/"+(shape.sharedMaterial!=null?shape.sharedMaterial.GetInstanceID():0);if(shape is BoxCollider box)s+="/"+box.center.ToString("R")+"/"+box.size.ToString("R");if(shape is MeshCollider mesh)s+="/"+(mesh.sharedMesh!=null?mesh.sharedMesh.GetInstanceID():0)+"/"+mesh.convex;return s;}
    Dictionary<Component,string> Snapshot()=>Physical().ToDictionary(c=>c,Config);
    void Same(Dictionary<Component,string> before){CollectionAssert.AreEquivalent(before.Keys,Physical());foreach(var pair in before)Assert.That(Config(pair.Key),Is.EqualTo(pair.Value),"Composition changed existing physical configuration: "+pair.Key.name);}
    object[] WheelOwners()=>trucks.SelectMany(t=>((Array)Get(t,"wheels")).Cast<object>()).ToArray();
    HashSet<Component> CurrentWheelColliders()=>new HashSet<Component>(WheelOwners().Select(w=>(Component)Get(Get(w,"wheel"),"meshCollider")).Where(c=>c!=null));
    Dictionary<Component,string> PersistentPhysical(){var generated=CurrentWheelColliders();return Physical().Where(c=>!generated.Contains(c)).ToDictionary(c=>c,Config);}
    Dictionary<object,string> GeneratedWheelGeometry()
    {
        var result=new Dictionary<object,string>();foreach(var wheel in WheelOwners()){var collider=(MeshCollider)Get(Get(wheel,"wheel"),"meshCollider");Assert.That(collider,Is.Not.Null);Assert.That(collider.transform.parent,Is.SameAs(((Component)wheel).transform),"Only the exact vendor wheel.meshCollider child may be replaced by original Initialize.");var material=collider.sharedMaterial;var mesh=collider.sharedMesh;Assert.That(mesh,Is.Not.Null);Assert.That(material,Is.Not.Null);result.Add(wheel,collider.attachedRigidbody.GetInstanceID()+"/"+collider.isTrigger+"/"+collider.convex+"/"+collider.cookingOptions+"/"+collider.contactOffset+"/"+collider.gameObject.layer+"/"+collider.hasModifiableContacts+"/"+collider.transform.localPosition.ToString("R")+"/"+collider.transform.localRotation.ToString("R")+"/"+collider.transform.localScale.ToString("R")+"/"+material.staticFriction+"/"+material.dynamicFriction+"/"+material.bounciness+"/"+material.frictionCombine+"/"+material.bounceCombine+"/"+string.Join(";",mesh.vertices.Select(v=>v.ToString("R")))+"/"+string.Join(",",mesh.triangles));}return result;
    }
    void SameVendorReset(Dictionary<Component,string> persistent,Dictionary<object,string> generated)
    {
        var actual=PersistentPhysical();CollectionAssert.AreEquivalent(persistent.Keys,actual.Keys,"Original Rigidbody/BoxCollider instances must survive every original round reset.");foreach(var pair in persistent)Assert.That(actual[pair.Key],Is.EqualTo(pair.Value),"Original body/shape physical configuration changed: "+pair.Key.name);var current=GeneratedWheelGeometry();CollectionAssert.AreEquivalent(generated.Keys,current.Keys);foreach(var pair in generated)Assert.That(current[pair.Key],Is.EqualTo(pair.Value),"Rebuilt vendor wheel collider geometry/material/owner differs: "+((Component)pair.Key).name);Assert.That(CurrentWheelColliders().Count,Is.EqualTo(64),"Exactly four original NWH generated colliders per sixteen trucks.");
    }
    string Wheels()=>string.Join(";",trucks.SelectMany(t=>((Array)Get(t,"wheels")).Cast<object>()).Select(w=>((Component)w).GetInstanceID()+"/"+Get(Get(w,"wheel"),"radius")+"/"+Get(Get(w,"wheel"),"width")+"/"+Get(Get(w,"spring"),"maxLength")+"/"+Get(Get(w,"spring"),"maxForce")));
    IEnumerator OriginalStartup()
    {
        var bindings=(Array)Get(match,"appearanceHosts");Set(match,"appearanceHosts",Array.CreateInstance(Sports("SportsTruckAppearanceHost"),0));try{Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));double deadline=Time.realtimeSinceStartupAsDouble+7;while(Time.realtimeSinceStartupAsDouble<deadline&&Get(match,"Phase").ToString()=="Settling")yield return null;Assert.That(Get(match,"Phase").ToString(),Is.EqualTo("Countdown"),"The original sixteen real NWH trucks must settle on the grid before controlled appearance trials.");}finally{Set(match,"appearanceHosts",bindings);}Call(match,"Pause",0,false);((Behaviour)match).enabled=false;yield return null;
    }
    void OriginalRound()
    {
        var bindings=(Array)Get(match,"appearanceHosts");Set(match,"appearanceHosts",Array.CreateInstance(Sports("SportsTruckAppearanceHost"),0));try{Call(match,"NewRound");}finally{Set(match,"appearanceHosts",bindings);}
    }
    void AssertArt(string first)
    {
        int count=(int)Get(Get(match,"setup"),"count");for(int i=0;i<4;i++)
        {
            if(i>=count){Assert.That(Get(hosts[i],"AppearanceRoot"),Is.Null);Assert.That(trucks[i].gameObject.activeSelf,Is.False);continue;}Assert.That(Get(hosts[i],"ProfileId"),Is.EqualTo(ids[i]));Assert.That(Get(hosts[i],"EffectiveBodyId"),Is.EqualTo(i==0?first:i%2==0?"truck.fire":"novelty.icecream"));var model=(Transform)Get(hosts[i],"AppearanceRoot");Assert.That(model,Is.Not.Null);Assert.That(model.GetComponentsInChildren<Collider>(true),Is.Empty);Assert.That(model.GetComponentsInChildren<Rigidbody>(true),Is.Empty);Assert.That(((Renderer[])Get(hosts[i],"originalBodyRenderers")).Length,Is.EqualTo(29));Assert.That(((Renderer[])Get(hosts[i],"originalBodyRenderers")).All(r=>!r.enabled),Is.True);Assert.That(((Renderer[])Get(hosts[i],"originalWheelRenderers")).All(r=>!r.enabled),Is.True);var entry=Call(Get(hosts[i],"catalog"),"FindBody",Get(hosts[i],"EffectiveBodyId"));var expected=((GameObject)Get(entry,"visualPrefab")).GetComponentsInChildren<Renderer>(true);var actual=(Renderer[])Get(hosts[i],"paintRenderers");Assert.That(actual.Length,Is.EqualTo(expected.Length));for(int r=0;r<actual.Length;r++)CollectionAssert.AreEqual(expected[r].sharedMaterials,actual[r].sharedMaterials,"Legacy Cheese paint must not retint selected atlas/glass/chrome materials.");
        }
    }
    MeshFilter[] OriginalBackgroundMeshes(Component truck)
    {
        var model=truck.transform.Find("NWH GR3D visual geometry");Assert.That(model,Is.Not.Null);var body=model.GetComponentsInChildren<MeshFilter>(true);Assert.That(body.Length,Is.EqualTo(29),"Only the exact original licensed body subtree belongs in the background geometry invariant.");var names=new[]{"Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR"};var wheels=((Array)Get(truck,"wheels")).Cast<object>().Select((wheel,index)=>{var filters=((Transform)Get(Get(wheel,"wheel"),"rotatingContainer")).GetComponentsInChildren<MeshFilter>(true);Assert.That(filters.Length,Is.EqualTo(1));Assert.That(filters[0].name,Is.EqualTo(names[index]));return filters[0];}).ToArray();Assert.That(wheels.Length,Is.EqualTo(4));var result=body.Concat(wheels).ToArray();Assert.That(result.Length,Is.EqualTo(33));
        var source=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Vehicles/Euro Truck by GR3D/SemiTruck.prefab");Assert.That(source,Is.Not.Null);var originals=source.GetComponentsInChildren<MeshFilter>(true);foreach(var filter in result){Assert.That(filter.sharedMesh,Is.Not.Null);Assert.That(filter.GetComponent<MeshRenderer>(),Is.Not.Null);Assert.That(originals.Any(original=>original.name==filter.name&&original.sharedMesh==filter.sharedMesh),Is.True,"Background body/wheel must retain its exact installed GR3D mesh identity: "+filter.name);}return result;
    }
    [UnityTest,Timeout(180000)]public IEnumerator FourScoringParticipantsUseAllSevenBodiesAfterRealGridResetWithoutChangingTwelveBackgroundRigs()
    {
        yield return Load();var initial=PersistentPhysical().Keys.ToArray();var background=trucks.Skip(4).ToArray();var meshes=background.SelectMany(OriginalBackgroundMeshes).ToArray();var art=meshes.Select(filter=>(Renderer)filter.GetComponent<MeshRenderer>()).ToArray();var markerType=Type.GetType("TMPro.TMP_Text, Unity.TextMeshPro",true);var markerTexts=trucks.Select(truck=>((Transform)Get(truck,"marker")).GetComponent(markerType)).ToArray();Assert.That(markerTexts.All(marker=>marker!=null),Is.True);var originalMarkerText=markerTexts.Select(marker=>(string)Get(marker,"text")).ToArray();var meshRefs=meshes.Select(m=>m.sharedMesh).ToArray();var materialRefs=art.Select(r=>r.sharedMaterials).ToArray();var originalWheels=trucks.SelectMany(t=>((Array)Get(t,"wheels")).Cast<object>()).ToArray();var containers=originalWheels.Select(w=>(Transform)Get(Get(w,"wheel"),"rotatingContainer")).ToArray();var gear=trucks.Select(t=>new[]{(Transform)Get(t,"marker"),((Component)Get(t,"splash")).transform}.Concat(((Array)Get(t,"tracks")).Cast<Component>().Select(track=>track.transform)).ToArray()).ToArray();yield return OriginalStartup();foreach(var part in initial)Assert.That(Physical().Contains(part),Is.True);var totals=((int[])Get(match,"totals")).ToArray();
        foreach(string body in new[]{"truck.fire","truck.monster","truck.lifted","semi.lowrider","novelty.hotdog","novelty.icecream","semi.standard"})
        {
            Save(ids[0],body);Call(match,"RefreshParticipants",false);OriginalRound();yield return null;yield return null;var persistent=PersistentPhysical();var generated=GeneratedWheelGeometry();string wheels=Wheels();foreach(var host in hosts)Call(host,"RestoreOriginal");Call(match,"NewRound");yield return null;yield return null;SameVendorReset(persistent,generated);var physical=Snapshot();for(int i=0;i<4;i++)Assert.That(Call(hosts[i],"Prepare",ids[i],Get(((Array)Get(Get(match,"setup"),"players")).GetValue(i),"color")),Is.EqualTo(true));Same(physical);Assert.That(Wheels(),Is.EqualTo(wheels));AssertArt(body);CollectionAssert.AreEqual(meshRefs,meshes.Select(m=>m.sharedMesh));for(int i=0;i<art.Length;i++)CollectionAssert.AreEqual(materialRefs[i],art[i].sharedMaterials);CollectionAssert.AreEqual(containers,originalWheels.Select(w=>(Transform)Get(Get(w,"wheel"),"rotatingContainer")));CollectionAssert.AreEqual(totals,(int[])Get(match,"totals"));
            for(int i=0;i<16;i++){Assert.That(((Transform)Get(trucks[i],"marker")).GetComponent(markerType),Is.SameAs(markerTexts[i]),"Preserve the actual TMP marker component; its generated glyph mesh may rebuild.");Assert.That(Get(markerTexts[i],"text"),Is.EqualTo(i<4?"P"+(i+1):originalMarkerText[i]));Assert.That(((Transform)Get(trucks[i],"marker")).gameObject.activeInHierarchy,Is.EqualTo(i<4));CollectionAssert.AreEqual(gear[i],new[]{(Transform)Get(trucks[i],"marker"),((Component)Get(trucks[i],"splash")).transform}.Concat(((Array)Get(trucks[i],"tracks")).Cast<Component>().Select(t=>t.transform)));if(i>=4){Assert.That(trucks[i].gameObject.activeSelf,Is.True);Assert.That(((Transform)Get(trucks[i],"marker")).gameObject.activeSelf,Is.False);Assert.That(trucks[i].GetComponent(Sports("SportsTruckAppearanceHost")),Is.Null);}}
            Call(hosts[0],"LateUpdate");foreach(var follower in ((IEnumerable)Get(hosts[0],"wheelVisuals")).Cast<object>()){var source=(Transform)Get(follower,"source");Assert.That(containers.Take(4).Contains(source),Is.True);Assert.That(Vector3.Distance(((Transform)Get(follower,"visual")).position,source.position+trucks[0].transform.up*(float)Get(follower,"verticalOffset")),Is.LessThan(3e-5));}
        }
        int revision=(int)Get(hosts[0],"AppearanceRevision");Call(match,"ChangeSetup");Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));Assert.That(Get(hosts[0],"AppearanceRevision"),Is.EqualTo(revision));AssertArt("semi.standard");Call(match,"Pause",0,false);var positions=trucks.Select(t=>t.transform.position).ToArray();yield return null;yield return null;CollectionAssert.AreEqual(positions,trucks.Select(t=>t.transform.position));Call(match,"Resume");Assert.That(Time.timeScale,Is.EqualTo(1));TestContext.WriteLine("CHEESE_APPEARANCE four actual stable participant IDs/all7 bodies, original16-truck grid settling and NWH reset, strict synchronous physical/wheel config, twelve unbound background mesh/material refs, marker/splash/tracks, follower containers, pause/rematch retained. Controlled samples, not full catch match/art/hardware acceptance.");
    }
    [UnityTest,Timeout(180000)]public IEnumerator ParticipantCountChangesRestoreInactiveMarkedRigsWithoutAssigningBackgroundIdentities()
    {
        yield return Load();yield return OriginalStartup();Call(match,"NewRound");foreach(int count in new[]{1,2,3,4,1,4}){Set(Get(match,"setup"),"count",count);Call(match,"RefreshParticipants",false);Call(match,"NewRound");yield return null;yield return null;AssertArt("truck.fire");for(int i=0;i<16;i++){Assert.That(trucks[i].gameObject.activeSelf,Is.EqualTo(i<count||i>=4));Assert.That(((Transform)Get(trucks[i],"marker")).gameObject.activeInHierarchy,Is.EqualTo(i<count),"Only scoring active truck markers may be visible; inactive child activeSelf is retained by the original pool.");}Assert.That(((Array)Get(match,"appearanceHosts")).Length,Is.EqualTo(4));for(int i=0;i<4;i++)Assert.That(Get(Registry("GetAppearance",ids[i]),"bodyId"),Is.EqualTo(i%2==0?"truck.fire":"novelty.icecream"));}Assert.That(ids.Distinct().Count(),Is.EqualTo(4));TestContext.WriteLine("CHEESE_APPEARANCE_COUNT actual scoring counts1..4 restore inactive original rendering and stable IDs; twelve background racers remain outside participant/appearance mapping.");
    }
}
#endif
